import React, { useEffect, useRef, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { useAuth } from "../context/AuthContext";

const GRADS = ["rt1","rt2","rt3","rt4","rt5","rt6"];

export default function RoomDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user }  = useAuth();

  const [room, setRoom]       = useState(null);
  const [reviews, setReviews] = useState([]);
  const [avgRating, setAvg]   = useState(null);
  const [loading, setLoading] = useState(true);
  const [guests, setGuests]   = useState(1);
  const [dates, setDates]     = useState({ startDate: "", endDate: "" });
  const [nights, setNights]   = useState(0);
  const [booking, setBooking] = useState(false);
  const [msg, setMsg]         = useState("");
  const [reviewForm, setReviewForm] = useState({ rating: 5, comment: "" });
  const [reviewMsg, setReviewMsg] = useState("");
  const [reviewLoading, setReviewLoading] = useState(false);
  const endDateRef = useRef(null);

  const grad = GRADS[Math.floor(Math.random() * GRADS.length)];

  useEffect(() => {
    axios.get(`/api/rooms/${id}`)
      .then(r => { setRoom(r.data.room); setReviews(r.data.reviews); setAvg(r.data.avgRating); })
      .catch(() => setMsg("Room not found."))
      .finally(() => setLoading(false));
  }, [id]);

  const calcAvg = (list) => (
    list.length
      ? (list.reduce((sum, r) => sum + r.rating, 0) / list.length).toFixed(2)
      : null
  );

  useEffect(() => {
    if (dates.startDate && dates.endDate) {
      const n = Math.ceil((new Date(dates.endDate) - new Date(dates.startDate)) / 86400000);
      setNights(n > 0 ? n : 0);
    }
  }, [dates]);

  const discountedPrice = room ? Math.round(room.pricePerNight * (1 - room.discountRate / 100)) : 0;
  const total = nights > 0 ? discountedPrice * nights + 25 + 43 : 0;

  const handleBook = () => {
    if (!user) { navigate("/auth"); return; }
    if (!dates.startDate || !dates.endDate || nights <= 0) { setMsg("Please select valid dates."); return; }
    navigate("/booking", { state: { room, dates, nights, total, guests } });
  };

  const toInputDate = (date) => date.toISOString().slice(0, 10);
  const addDays = (dateString, days) => {
    const base = new Date(dateString);
    return toInputDate(new Date(base.getTime() + days * 86400000));
  };
  const today = toInputDate(new Date());
  const minCheckout = dates.startDate
    ? addDays(dates.startDate, 1)
    : today;

  const onStartDateChange = (value) => {
    setDates((prev) => {
      const next = { ...prev, startDate: value };
      if (next.endDate && next.endDate <= value) {
        next.endDate = "";
      }
      return next;
    });
  };


  const handleReviewSubmit = async (e) => {
    e.preventDefault();
    if (!user) { navigate("/auth"); return; }
    if (!reviewForm.comment.trim()) { setReviewMsg("Please add a comment."); return; }
    setReviewLoading(true); setReviewMsg("");
    try {
      const { data } = await axios.post("/api/reviews", {
        roomId: room._id,
        rating: Number(reviewForm.rating),
        comment: reviewForm.comment.trim(),
      });
      const nextReviews = [data.review, ...reviews];
      setReviews(nextReviews);
      setAvg(calcAvg(nextReviews));
      setReviewForm({ rating: 5, comment: "" });
      setReviewMsg("Review submitted.");
    } catch (err) {
      setReviewMsg(err.response?.data?.message || "Could not submit review.");
    } finally {
      setReviewLoading(false);
    }
  };

  if (loading) return <div style={{ padding: 80, textAlign: "center", color: "var(--muted)" }}>Loading…</div>;
  if (!room)   return <div style={{ padding: 80, textAlign: "center", color: "var(--coral)" }}>{msg || "Room not found."}</div>;

  const services = room.services ? room.services.split(",").map(s => s.trim()) : [];
  const svcIcon = (s) => {
    const l = s.toLowerCase();
    if (l.includes("wifi"))  return "📶";
    if (l.includes("ac"))    return "❄️";
    if (l.includes("park"))  return "🅿️";
    if (l.includes("pool"))  return "🌊";
    if (l.includes("gym"))   return "🏋️";
    if (l.includes("kitch")) return "🍳";
    if (l.includes("break")) return "☕";
    if (l.includes("tv"))    return "📺";
    return "✨";
  };

  const gallery = room.images?.length
    ? room.images
    : Array.from({ length: 6 }, (_, i) => `https://picsum.photos/seed/roomly-${room._id || id}-${i}/1200/800`);

  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: "36px 40px" }}>
      {/* Breadcrumb */}
      <div style={{ fontSize: 13, color: "var(--muted)", marginBottom: 18 }}>
        <span style={{ color: "var(--gold)", cursor: "pointer" }} onClick={() => navigate("/")}>Home</span>
        {" → "}
        <span style={{ color: "var(--gold)", cursor: "pointer" }} onClick={() => navigate("/explore")}>{room.city}</span>
        {" → "}{room.location}
      </div>

      {/* Photo Grid */}
      <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gridTemplateRows: "240px 180px", gap: 10, borderRadius: "var(--r-lg)", overflow: "hidden", marginBottom: 32 }}>
        <div
          className={grad}
          style={{
            gridRow: "1/3",
            backgroundImage: `url(${gallery[0]})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        />
        <div
          style={{
            backgroundImage: `url(${gallery[1] || gallery[0]})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        />
        <div style={{ position: "relative", backgroundImage: `url(${gallery[2] || gallery[0]})`, backgroundSize: "cover", backgroundPosition: "center" }}>
          <div style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,.45)", color: "white", fontWeight: 600, fontSize: 14, display: "flex", alignItems: "center", justifyContent: "center" }}>+{gallery.length} photos</div>
        </div>
      </div>

      {/* Layout */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 350px", gap: 40, alignItems: "flex-start" }}>
        {/* Left */}
        <div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
            <h1 style={{ fontFamily: "'DM Serif Display',serif", fontSize: 30, marginBottom: 12 }}>{room.title || room.description?.substring(0, 50) || room.type}</h1>
            <div style={{ display: "flex", gap: 8 }}>
              <button style={{ width: 38, height: 38, border: "1px solid var(--border)", borderRadius: "50%", background: "white", cursor: "pointer", fontSize: 15 }}>🔗</button>
              <button style={{ width: 38, height: 38, border: "1px solid var(--border)", borderRadius: "50%", background: "white", cursor: "pointer", fontSize: 15 }}>♡</button>
            </div>
          </div>

          <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 18, flexWrap: "wrap", fontSize: 13, color: "var(--muted)" }}>
            <span className="badge bd-gold">{room.type}</span>
            {avgRating && <div style={{ display: "flex", alignItems: "center", gap: 5, fontWeight: 600, fontSize: 14 }}>★ {avgRating} <span style={{ color: "var(--muted)", fontWeight: 400 }}>({reviews.length} reviews)</span></div>}
            <span>📍 {room.location}, {room.city}</span>
          </div>

          <div style={{ display: "flex", gap: 20, fontSize: 14, color: "var(--muted)", marginBottom: 22, flexWrap: "wrap" }}>
            <span>👥 Max {room.maxGuests} guests</span>
            <span>🛏 {room.beds_num} bed{room.beds_num > 1 ? "s" : ""}</span>
            {room.space && <span>📐 {room.space} m²</span>}
          </div>

          {/* Price highlight */}
          <div style={{ background: "var(--gold-lt)", border: "1px solid rgba(200,151,90,.3)", borderRadius: "var(--r-md)", padding: "14px 18px", marginBottom: 20, display: "flex", alignItems: "center", gap: 16 }}>
            <div>
              <div style={{ fontFamily: "'DM Serif Display',serif", fontSize: 26 }}>
                ${discountedPrice}<span style={{ fontFamily: "'Sora',sans-serif", fontSize: 14, fontWeight: 400, color: "var(--muted)" }}>/night</span>
              </div>
              {room.discountRate > 0 && <div style={{ fontSize: 12, color: "var(--coral)", fontWeight: 600 }}>{room.discountRate}% discount · Was ${room.pricePerNight}</div>}
            </div>
            <div style={{ marginLeft: "auto" }}><span className="badge bd-teal">Available</span></div>
          </div>

          <div className="divider" />

          <p style={{ fontSize: 15, lineHeight: 1.78, color: "var(--muted)", marginBottom: 26 }}>{room.description}</p>

          {/* Amenities */}
          {services.length > 0 && (
            <>
              <h4 style={{ fontWeight: 600, fontSize: 15, marginBottom: 14 }}>What this place offers</h4>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 28 }}>
                {services.map((s, i) => (
                  <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 14 }}>
                    <span style={{ fontSize: 17 }}>{svcIcon(s)}</span>{s}
                  </div>
                ))}
              </div>
            </>
          )}

          <div className="divider" />

          {/* Reviews */}
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 20 }}>
            <h2 className="h3">★ {avgRating || "—"}</h2>
            <span style={{ color: "var(--muted)", fontSize: 14 }}>· {reviews.length} reviews</span>
          </div>
          {reviews.length === 0 ? (
            <p style={{ color: "var(--muted)", fontSize: 14 }}>No reviews yet. Be the first to review!</p>
          ) : (
            reviews.map(r => (
              <div key={r._id} style={{ background: "var(--cream)", border: "1px solid var(--border)", borderRadius: "var(--r-md)", padding: 16, marginBottom: 12 }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 10 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <div style={{ width: 34, height: 34, borderRadius: "50%", background: "var(--gold-lt)", color: "var(--gold-dk)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 600 }}>
                      {r.userId?.first_name?.[0]}{r.userId?.last_name?.[0]}
                    </div>
                    <div>
                      <div style={{ fontWeight: 600, fontSize: 13 }}>{r.userId?.first_name} {r.userId?.last_name}</div>
                      <div style={{ fontSize: 11, color: "var(--muted)" }}>{new Date(r.createdAt).toLocaleDateString("en-US", { month: "short", year: "numeric" })}</div>
                    </div>
                  </div>
                  <div style={{ color: "var(--gold)", fontSize: 13 }}>{"★".repeat(r.rating)}</div>
                </div>
                <p style={{ fontSize: 14, lineHeight: 1.65 }}>{r.comment}</p>
              </div>
            ))
          )}

          {/* Review Form */}
          <div style={{ marginTop: 22, paddingTop: 18, borderTop: "1px solid var(--border)" }}>
            {!user ? (
              <p style={{ fontSize: 13, color: "var(--muted)" }}>Sign in to leave a review.</p>
            ) : reviews.some(r => r.userId?._id === user._id) ? (
              <p style={{ fontSize: 13, color: "var(--muted)" }}>You already reviewed this room.</p>
            ) : (
              <form onSubmit={handleReviewSubmit}>
                <div style={{ display: "flex", gap: 12, marginBottom: 10 }}>
                  <label style={{ fontSize: 12, fontWeight: 600 }}>Rating</label>
                  <select
                    value={reviewForm.rating}
                    onChange={e => setReviewForm(p => ({ ...p, rating: e.target.value }))}
                    style={{ border: "1px solid var(--border)", borderRadius: "var(--r-sm)", padding: "6px 8px", fontFamily: "'Sora',sans-serif", fontSize: 13 }}
                  >
                    {[5,4,3,2,1].map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </div>
                <textarea
                  rows={3}
                  placeholder="Share your experience..."
                  value={reviewForm.comment}
                  onChange={e => setReviewForm(p => ({ ...p, comment: e.target.value }))}
                  style={{ width: "100%", border: "1px solid var(--border)", borderRadius: "var(--r-sm)", padding: "10px 12px", fontFamily: "'Sora',sans-serif", fontSize: 13, resize: "vertical" }}
                />
                {reviewMsg && <p style={{ fontSize: 12, color: reviewMsg === "Review submitted." ? "var(--teal)" : "var(--coral)", marginTop: 8 }}>{reviewMsg}</p>}
                <button className="btn btn-dark" type="submit" disabled={reviewLoading} style={{ marginTop: 10, padding: "8px 14px", fontSize: 13 }}>
                  {reviewLoading ? "Submitting..." : "Submit Review"}
                </button>
              </form>
            )}
          </div>
        </div>

        {/* ── Booking Card ── */}
        <div style={{ background: "white", border: "1.5px solid var(--border)", borderRadius: "var(--r-xl)", padding: 26, boxShadow: "var(--sh-lg)", position: "sticky", top: "calc(var(--nav-h) + 20px)", width: "100%" }}>
          <div style={{ marginBottom: 20 }}>
            <span style={{ fontFamily: "'DM Serif Display',serif", fontSize: 28 }}>${discountedPrice}</span>
            <span style={{ fontSize: 14, color: "var(--muted)" }}> / night</span>
            {room.discountRate > 0 && <span style={{ fontSize: 13, color: "var(--coral)", fontWeight: 600, marginLeft: 6 }}>−{room.discountRate}%</span>}
            {avgRating && <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 4 }}>★ {avgRating} · {reviews.length} reviews</div>}
          </div>

          {/* Date inputs */}
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", border: "1px solid var(--border)", borderRadius: "var(--r-md)", overflow: "hidden", marginBottom: 10 }}>
            {[["Check-in","startDate"],["Check-out","endDate"]].map(([lbl, key], i) => (
              <div key={key} style={{ padding: "12px 14px", borderRight: i === 0 ? "1px solid var(--border)" : "none" }}>
                <label style={{ display: "block", fontSize: 10, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: "var(--muted)", marginBottom: 3 }}>{lbl}</label>
                <input
                  ref={key === "endDate" ? endDateRef : null}
                  type="date"
                  value={dates[key]}
                  min={key === "startDate" ? today : minCheckout}
                  onChange={e => (key === "startDate" ? onStartDateChange(e.target.value) : setDates(p => ({ ...p, [key]: e.target.value })))}
                  style={{
                    border: "none",
                    outline: "none",
                    fontFamily: "'Sora',sans-serif",
                    fontSize: 14,
                    fontWeight: 500,
                    background: "transparent",
                    width: "100%",
                    cursor: "pointer",
                    padding: "2px 4px",
                  }}
                />
              </div>
            ))}
          </div>

          {/* Guests */}
          <div style={{ border: "1px solid var(--border)", borderRadius: "var(--r-md)", padding: "12px 14px", marginBottom: 18, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div>
              <label style={{ fontSize: 10, fontWeight: 700, letterSpacing: ".8px", textTransform: "uppercase", color: "var(--muted)", display: "block", marginBottom: 3 }}>Guests</label>
              <div style={{ fontSize: 14, fontWeight: 500 }}>{guests} guest{guests > 1 ? "s" : ""} (max {room.maxGuests})</div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <button onClick={() => setGuests(g => Math.max(1, g - 1))} style={{ width: 28, height: 28, border: "1px solid var(--border)", borderRadius: "50%", background: "white", cursor: "pointer", fontSize: 16, display: "flex", alignItems: "center", justifyContent: "center" }}>−</button>
              <span style={{ fontWeight: 600 }}>{guests}</span>
              <button onClick={() => setGuests(g => Math.min(room.maxGuests, g + 1))} style={{ width: 28, height: 28, border: "1px solid var(--border)", borderRadius: "50%", background: "white", cursor: "pointer", fontSize: 16, display: "flex", alignItems: "center", justifyContent: "center" }}>+</button>
            </div>
          </div>

          {msg && <p style={{ color: "var(--coral)", fontSize: 13, marginBottom: 10 }}>{msg}</p>}

          <button className="btn btn-gold" onClick={handleBook} style={{ width: "100%", justifyContent: "center", padding: 14, fontSize: 15 }}>
            Reserve & Verify ID →
          </button>
          <p style={{ textAlign: "center", fontSize: 12, color: "var(--muted)", marginTop: 8 }}>You won't be charged yet · National ID required</p>

          {nights > 0 && (
            <div style={{ fontSize: 13, borderTop: "1px solid var(--border)", paddingTop: 14, marginTop: 14 }}>
              {[
                [`$${discountedPrice} × ${nights} nights`, `$${discountedPrice * nights}`],
                ["Cleaning fee", "$25"],
                ["Roomly service fee", "$43"],
              ].map(([l, v]) => (
                <div key={l} style={{ display: "flex", justifyContent: "space-between", marginBottom: 8, color: "var(--muted)" }}>
                  <span>{l}</span><span>{v}</span>
                </div>
              ))}
              <div style={{ display: "flex", justifyContent: "space-between", fontWeight: 600, color: "var(--charcoal)", fontSize: 15, borderTop: "1px solid var(--border)", paddingTop: 12, marginTop: 4 }}>
                <span>Total (USD)</span><span>${total}</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
